def _data(apps, schema_editor):
    """Correction 06: only ns, logs, admin, backup and the route reflectors of each BGP network stay core services (the
    other records go; their VMs are not touched); the kept ones get their type and what their form asks. Empty templates
    for the base-OS services."""
    CoreService = apps.get_model("inventory", "CoreService")
    PlatformDatastore = apps.get_model("inventory", "PlatformDatastore")
    Network = apps.get_model("inventory", "Network")
    ConfigTemplate = apps.get_model("inventory", "ConfigTemplate")
    for role, name in TEMPLATES:
        ConfigTemplate.objects.get_or_create(role=role, defaults={"name": name, "os": "base-os", "body": "",
                                                                  "description": "Empty for now: the requirements follow."})
    for s in CoreService.objects.all():
        role = ConfigTemplate.objects.filter(pk=s.template_id).values_list("role", flat=True).first() or ""
        if s.name in DELETE:
            s.delete()
            continue
        params = dict(s.params or {})
        if role.startswith("rr-"):
            ids = [s.nic1_network_id] + [x.get("network") for x in (s.more_nics or [])]
            net = Network.objects.filter(pk__in=[int(i) for i in ids if i], kind__in=["ix", "evpn"]).first()
            s.stype, params["network"] = "bgp-rr", (net.pk if net else None)
        elif s.name in KEEP:
            s.stype = KEEP[s.name]
        elif s.name.endswith("-backup"):
            s.stype = "backup"
            ds = list(PlatformDatastore.objects.filter(platform_id=s.serves_id, kind="backups")) if s.serves_id else []
            params["datastore"] = ds[0].pk if len(ds) == 1 else None
        else:
            s.stype = "core-vm"
        params.update(vcpu=s.vcpu, ram_gb=s.ram_gb, disk_gb=s.disk_gb)
        s.params = params
        s.save(update_fields=["stype", "params"])


